  constructor(message: string, status: number, statusCode: string) {
    super(message)
    this.name = 'StorageVectorsApiError'
    this.status = status
    this.statusCode = statusCode
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      status: this.status,
      statusCode: this.statusCode,
    }
  }
}

